import { FaCheckCircle } from 'react-icons/fa';
import { useTranslation } from 'react-i18next';
import { Box, Center, Flex, HStack, Stack, styled } from 'styled-system/jsx';
import { Text } from '~/components/ui/text';
import { Link } from '~/components/ui/link';
import { useBluebirdAuthors } from '~/hooks/useBluebirdAuthors';
import { Spinner } from '~/components/ui/spinner';
import { formatProfilePictureUrl } from '~/utils/image';
import { formatTweetText } from '~/components/bluebird/TweetEntities';
import MainContentAndRightSidebar from '~/components/layout/MainContentAndRightSidebar';

const CheckCircle = styled(FaCheckCircle);

export default function Page() {
  const { data: authors, isLoading, isError, error } = useBluebirdAuthors();
  const { t } = useTranslation();

  return (
    <MainContentAndRightSidebar rightSidebarContent={() => <Box></Box>}>
      <Box className="container" w="full">
        {isLoading ? (
          <Center py="4">
            <Stack alignItems="center">
              <Spinner />
              <Text>{t('bluebird.members.loading')}</Text>
            </Stack>
          </Center>
        ) : isError ? (
          <Center py="4">
            <Text>
              {t('bluebird.members.error')}
              {error?.message}
            </Text>
          </Center>
        ) : authors?.length === 0 ? (
          <Center py="4">
            <Text>{t('bluebird.members.noMembers')}</Text>
          </Center>
        ) : (
          <styled.ul className="space-y-2">
            {authors?.map((author) => (
              <styled.li
                key={author.id}
                data-author-id={author.id}
                display="flex"
                borderBottomWidth="1px"
                borderColor="border.default"
                transitionDuration="200ms"
                transitionProperty="colors"
                _hover={{ bg: 'bg.subtle' }}
              >
                <Link
                  href={author.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  style={{ display: 'flex', width: '100%' }}
                  textDecoration="unset"
                >
                  <Flex direction="column" flexGrow="1" minW="0" overflow="hidden">
                    <Box
                      style={{
                        backgroundImage: `url(${author.coverPicture || 'https://via.placeholder.com/500x200'})`
                      }}
                      w="full"
                      h="12rem"
                      bgPosition="center"
                      bgSize="cover"
                    />
                    <Stack position="relative" gap="0.5" p="4" py="6">
                      <Flex
                        position="absolute"
                        top="0"
                        transform="translateY(calc(-100% + 1rem))"
                        flexShrink="0"
                        mr="1rem"
                      >
                        <styled.img
                          src={formatProfilePictureUrl(author.profilePicture)}
                          alt={author.name}
                          objectFit="cover"
                          border="4px solid"
                          borderColor="bg.default"
                          borderRadius="full"
                          w="20"
                          h="20"
                        />
                      </Flex>
                      <Stack gap="0.5">
                        <HStack gap="0.25rem" alignItems="center" mb="0.125rem" flexWrap="wrap">
                          <HStack flexGrow="1" alignItems="center">
                            <Text
                              color="fg.default"
                              textOverflow="ellipsis"
                              fontWeight="bold"
                              overflow="hidden"
                              whiteSpace="nowrap"
                            >
                              {author.name}
                            </Text>
                            {author.isBlueVerified && <CheckCircle size="1rem" color="blue.500" />}
                            <Text
                              ml="0.25rem"
                              color="fg.muted"
                              textOverflow="ellipsis"
                              fontSize="0.875rem"
                              overflow="hidden"
                              whiteSpace="nowrap"
                            >
                              @{author.userName}
                            </Text>
                          </HStack>
                        </HStack>
                        <Text
                          w="full"
                          color="fg.default"
                          wordBreak="break-word"
                          fontSize="1rem"
                          lineHeight="normal"
                          whiteSpace="pre-wrap"
                        >
                          {formatTweetText(
                            author.profile_bio?.description || '',
                            author.profile_bio?.entities.description || {}
                          )}
                        </Text>
                        {author.profile_bio.entities.url.urls &&
                          author.profile_bio.entities.url.urls.length > 0 && (
                            <Stack gap="1" mt="2">
                              {author.profile_bio.entities.url.urls.map((urlEntity) => (
                                <Link
                                  key={urlEntity.url}
                                  href={urlEntity.url}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  color="colorPalette.default"
                                  fontSize="sm"
                                >
                                  {urlEntity.expanded_url}
                                </Link>
                              ))}
                            </Stack>
                          )}
                      </Stack>
                    </Stack>
                  </Flex>
                </Link>
              </styled.li>
            ))}
          </styled.ul>
        )}
      </Box>
    </MainContentAndRightSidebar>
  );
}
